UPDATE COTIZACION_ESTADOS SET FECHA = DATEADD(-60487 MINUTE TO CURRENT_TIMESTAMP), USUARIO_ID = (SELECT ID FROM USUARIOS WHERE CORREO = 'asistente@anovo.test') WHERE ID = (SELECT ID FROM COTIZACION_ESTADOS WHERE COTIZACION_ID = (SELECT C.ID FROM COTIZACIONES C JOIN SOLICITUDES S ON S.ID = C.SOLICITUD_ID WHERE S.UUID_LOCAL = '28487051-4a4b-5d2b-bc05-f9c97c9eb8ea') AND ESTADO = 'pendiente' ORDER BY ID ROWS 1 TO 1);
COMMIT;

ALTER TRIGGER TR_COTIZACIONES_BU INACTIVE;
ALTER TRIGGER TR_SOLICITUDES_BU INACTIVE;
COMMIT;
UPDATE COTIZACIONES C SET FECHA_MODIFICACION = (SELECT MAX(E.FECHA) FROM COTIZACION_ESTADOS E WHERE E.COTIZACION_ID = C.ID);
UPDATE SOLICITUDES S SET FECHA_MODIFICACION = COALESCE((SELECT MIN(C.FECHA_ELABORACION) FROM COTIZACIONES C WHERE C.SOLICITUD_ID = S.ID), S.FECHA_RECEPCION);
COMMIT;
ALTER TRIGGER TR_COTIZACIONES_BU ACTIVE;
ALTER TRIGGER TR_SOLICITUDES_BU ACTIVE;
COMMIT;

/* ====================  RESUMEN  ==================== */
SELECT 'USUARIOS ACTIVOS' AS TABLA, COUNT(*) AS FILAS FROM USUARIOS WHERE ACTIVO = TRUE
UNION ALL SELECT 'CLIENTES', COUNT(*) FROM CLIENTES
UNION ALL SELECT 'CLIENTE_CONTACTOS', COUNT(*) FROM CLIENTE_CONTACTOS
UNION ALL SELECT 'CONSENTIMIENTO_HISTORIAL', COUNT(*) FROM CLIENTE_CONSENTIMIENTO_HISTORIAL
UNION ALL SELECT 'SOLICITUDES', COUNT(*) FROM SOLICITUDES
UNION ALL SELECT 'SOLICITUD_PIEZAS', COUNT(*) FROM SOLICITUD_PIEZAS
UNION ALL SELECT 'SOLICITUD_ADJUNTOS', COUNT(*) FROM SOLICITUD_ADJUNTOS
UNION ALL SELECT 'SOLICITUD_MEDIDAS', COUNT(*) FROM SOLICITUD_MEDIDAS
UNION ALL SELECT 'COTIZACIONES', COUNT(*) FROM COTIZACIONES
UNION ALL SELECT 'COTIZACION_DETALLE', COUNT(*) FROM COTIZACION_DETALLE
UNION ALL SELECT 'COTIZACION_ESTADOS', COUNT(*) FROM COTIZACION_ESTADOS
UNION ALL SELECT 'COTIZACION_ENVIOS', COUNT(*) FROM COTIZACION_ENVIOS;
SELECT ESTADO, COUNT(*) FROM COTIZACIONES GROUP BY ESTADO;
